// Voice library — curated catalog for /voices.
// Each entry maps a Callen-branded persona to an underlying Microsoft
// neural voice. Sample mp3s are pre-generated by scripts/generate-voices.mjs
// from the `sample` text below, using `edgeVoice` + the prosody settings.
//
// Heavy Urdu coverage (ur-PK-AsadNeural + ur-PK-UzmaNeural) plus a smaller
// English spread (US, Indian, British), reflecting the Callen product focus
// on Pakistani telephony. Bilingual code-mix included since real Pakistani
// callers switch mid-sentence.

export type VoiceLanguage = "Urdu" | "English" | "Urdu + English";
export type VoiceAccent =
  | "Pakistani"
  | "Indian"
  | "American"
  | "British"
  | "Bilingual";
export type VoiceGender = "Male" | "Female";
export type VoiceAge = "Young adult" | "Adult" | "Middle aged";
export type VoiceCategory =
  | "Conversational"
  | "Customer Service"
  | "Sales"
  | "Receptionist"
  | "Order Taking"
  | "Healthcare"
  | "Narration"
  | "Concierge";

export type Voice = {
  id: string;
  name: string;
  tagline: string;        // short character description shown on card
  edgeVoice: string;      // Microsoft Edge neural voice (used by generator)
  rate?: string;          // SSML rate e.g. "+10%" or "-5%"
  pitch?: string;         // SSML pitch e.g. "+0Hz"
  language: VoiceLanguage;
  extraLanguages?: VoiceLanguage[];   // for the "+N" overflow chip on cards
  accent: VoiceAccent;
  gender: VoiceGender;
  age: VoiceAge;
  category: VoiceCategory;
  useCases: VoiceCategory[];          // shown in detail sheet
  sample: string;                     // text used by the generator and shown in sheet
  premium?: boolean;
  trending?: boolean;
  audioSrc: string;                   // /voices/<id>.mp3
};

